class SmoothScrollAll{constructor(){this.ease=.1,this.elements=new Set(),this.onWheel=this.onWheel.bind(this),this.animate=this.animate.bind(this),this.observeDOM(),this.initScrollables(),this.animate()}observeDOM(){new MutationObserver(m=>{m.forEach(o=>{o.addedNodes.forEach(n=>{if(n.nodeType===1){this.checkScrollable(n);n.querySelectorAll&&n.querySelectorAll("*").forEach(e=>this.checkScrollable(e))}})})}).observe(document.body,{childList:true,subtree:true})}initScrollables(){this.elements.clear();[...document.querySelectorAll("*")].forEach(e=>this.checkScrollable(e));this.checkScrollable(window)}checkScrollable(e){const s=getComputedStyle(e),vert=(e.scrollHeight>e.clientHeight&&(s.overflowY==="auto"||s.overflowY==="scroll")),hor=(e.scrollWidth>e.clientWidth&&(s.overflowX==="auto"||s.overflowX==="scroll"));if((vert||hor)&&!this.elements.has(e)){this.elements.add(e);e._targetScrollTop=e.scrollTop||0;e._targetScrollLeft=e.scrollLeft||0;e.addEventListener("wheel",ev=>this.onWheel(ev,e),{passive:false})}else if((e===window||e===document.body||e===document.documentElement)&&!this.elements.has(window)){this.elements.add(window);window._targetScrollTop=window.scrollY||0;window._targetScrollLeft=window.scrollX||0;window.addEventListener("wheel",ev=>this.onWheel(ev,window),{passive:false})}}onWheel(e,t){e.preventDefault();const deltaY=e.deltaY,deltaX=e.deltaX;if(t===window){t._targetScrollTop=Math.min(Math.max(t._targetScrollTop+deltaY,0),document.documentElement.scrollHeight-window.innerHeight);t._targetScrollLeft=Math.min(Math.max(t._targetScrollLeft+deltaX,0),document.documentElement.scrollWidth-window.innerWidth)}else{t._targetScrollTop=Math.min(Math.max(t._targetScrollTop+deltaY,0),t.scrollHeight-t.clientHeight);t._targetScrollLeft=Math.min(Math.max(t._targetScrollLeft+deltaX,0),t.scrollWidth-t.clientWidth)}}animate(){this.elements.forEach(e=>{if(e===window){const st=window.scrollY,sl=window.scrollX,dy=e._targetScrollTop-st,dx=e._targetScrollLeft-sl;Math.abs(dy)>0.5||Math.abs(dx)>0.5?window.scrollTo(sl+dx*this.ease,st+dy*this.ease):window.scrollTo(e._targetScrollLeft,e._targetScrollTop)}else{const st=e.scrollTop,sl=e.scrollLeft,dy=e._targetScrollTop-st,dx=e._targetScrollLeft-sl;if(Math.abs(dy)>0.5||Math.abs(dx)>0.5){e.scrollTop=st+dy*this.ease;e.scrollLeft=sl+dx*this.ease}else{e.scrollTop=e._targetScrollTop;e.scrollLeft=e._targetScrollLeft}}});requestAnimationFrame(this.animate)}}document.addEventListener("DOMContentLoaded",()=>new SmoothScrollAll());
